import json
import csv

# Load gasstations data
with open('json/gasstations.json', 'r') as f:
    gasstations = json.load(f)

# Build chain_id -> country mapping
cs_by_chain = {}
for r in gasstations['records']:
    chain = r['ChainID']
    country = r['Country']
    if chain not in cs_by_chain:
        cs_by_chain[chain] = set()
    cs_by_chain[chain].add(country)

# Check if any chain has multiple countries
multi_country_chains = {c: countries for c, countries in cs_by_chain.items() if len(countries) > 1}
print(f"Chains with multiple countries: {len(multi_country_chains)}")
if multi_country_chains:
    print(list(multi_country_chains.items())[:5])
else:
    print("Each chain is associated with exactly one country")

# Create final chain->country map
chain_to_country = {c: list(countries)[0] for c, countries in cs_by_chain.items()}
print(f"Total chains: {len(chain_to_country)}")

